package com.braseiro.dnd5e;

import org.json.JSONArray;
import org.json.JSONObject;

import java.util.Locale;

/**
 * Compiled, source-bound downtime procedures from Xanathar's Guide to Everything ch. 2.
 * No random roll is generated here: roll/check totals are explicit player/host inputs.
 */
public final class XanatharDowntimeRulesEngine {
    public static final String BOOK="Xanathar's Guide to Everything";
    public static final String PACK="Xanathar — Downtime Revisited";
    private XanatharDowntimeRulesEngine(){}

    public static JSONObject descriptor(){JSONObject o=new JSONObject();try{o.put("id","xanathar_downtime_revisited").put("book",BOOK).put("status","compiled")
            .put("source_pages","123-134").put("official_errata_applied",new JSONArray().put("Research p.132: both 100 gp references corrected to 50 gp"))
            .put("auto_rolls",false).put("procedures",new JSONArray()
                    .put("buy_magic_item").put("carouse").put("craft_item").put("craft_magic_item").put("craft_healing_potion")
                    .put("crime").put("gambling").put("pit_fighting").put("relax").put("religious_service").put("research")
                    .put("scribe_scroll").put("sell_magic_item").put("training").put("work"));}catch(Exception ignored){}return o;}

    public static JSONObject execute(String ruleId,JSONObject raw){JSONObject in=raw==null?new JSONObject():raw;String id=ruleId==null?"":ruleId.trim();
        if(id.equals("xanathar.downtime.buy_magic_item"))return buyMagicItem(in);
        if(id.equals("xanathar.downtime.carouse"))return carouse(in);
        if(id.equals("xanathar.downtime.craft_item"))return craftItem(in);
        if(id.equals("xanathar.downtime.craft_magic_item"))return craftMagicItem(in);
        if(id.equals("xanathar.downtime.craft_healing_potion"))return craftHealingPotion(in);
        if(id.equals("xanathar.downtime.crime"))return crime(in);
        if(id.equals("xanathar.downtime.gambling"))return gambling(in);
        if(id.equals("xanathar.downtime.pit_fighting"))return pitFighting(in);
        if(id.equals("xanathar.downtime.relax"))return relax(in);
        if(id.equals("xanathar.downtime.religious_service"))return religiousService(in);
        if(id.equals("xanathar.downtime.research"))return research(in);
        if(id.equals("xanathar.downtime.scribe_scroll"))return scribeScroll(in);
        if(id.equals("xanathar.downtime.sell_magic_item"))return sellMagicItem(in);
        if(id.equals("xanathar.downtime.training"))return training(in);
        if(id.equals("xanathar.downtime.work"))return work(in);
        return blocked("unknown_xanathar_downtime_rule");
    }

    public static JSONObject buyMagicItem(JSONObject in){JSONObject o=base(126);try{
        int weeks=Math.max(0,in.optInt("workweeks",0));double spent=Math.max(0,in.optDouble("search_gold",0));int check=in.optInt("persuasion_total",0);int magicMod=clamp(in.optInt("campaign_magic_modifier",0),-10,10);
        if(weeks<1||spent<100)return blocked(o,"requires_at_least_one_workweek_and_100_gp");
        int bonus=Math.min(10,Math.max(0,weeks-1)+(int)Math.floor(Math.max(0,spent-100)/100d));int total=check+bonus+magicMod;String table;String count;
        if(total<=5){table="A";count="1d6";}else if(total<=10){table="B";count="1d4";}else if(total<=15){table="C";count="1d4";}else if(total<=20){table="D";count="1d4";}else if(total<=25){table="E";count="1d4";}else if(total<=30){table="F";count="1d4";}else if(total<=35){table="G";count="1d4";}else if(total<=40){table="H";count="1d4";}else{table="I";count="1d4";}
        o.put("search_bonus",bonus).put("effective_total",total).put("dm_magic_item_table",table).put("items_to_roll",count).put("complication_roll","DM optional").put("price_formula",priceFormula(in.optString("rarity"))).put("consumable_halves_price",true);
        String rarity=norm(in.optString("rarity"));if(!rarity.isEmpty())o.put("specific_item_threshold",rarityThreshold(rarity)).put("specific_item_available_by_threshold",total>=rarityThreshold(rarity));
        if(in.has("price_dice_total")&&!rarity.isEmpty()){double price=priceFromDice(rarity,in.optDouble("price_dice_total"),in.optBoolean("consumable",false));if(in.optBoolean("low_magic_double_price",false))price*=2;o.put("asking_price_gp",price);}
        return o;
    }catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject carouse(JSONObject in){JSONObject o=base(127);try{String social=norm(in.optString("social_class"));int cost="low".equals(social)||"baixa".equals(social)?10:("middle".equals(social)||"media".equals(social)?50:("high".equals(social)||"alta".equals(social)?250:-1));if(cost<0)return blocked(o,"social_class_must_be_low_middle_or_high");if(in.optDouble("gold_available",0)<cost)return blocked(o,"insufficient_gold");if(("high".equals(social)||"alta".equals(social))&&!in.optBoolean("high_class_access",false))return blocked(o,"high_class_access_required");int t=in.optInt("persuasion_total",0),allied=0,hostile=0;if(t<=5)hostile=1;else if(t<=10){}else if(t<=15)allied=1;else if(t<=20)allied=2;else allied=3;int maxUnspecified=Math.max(1,1+in.optInt("charisma_modifier",0));return o.put("workweeks",1).put("gold_cost",cost).put("allied_contacts_gained",allied).put("hostile_contacts_gained",hostile).put("max_unspecified_allied_contacts",maxUnspecified).put("contact_help_is_single_use",true).put("complication_chance_percent",10);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject craftItem(JSONObject in){JSONObject o=base(128);try{double price=Math.max(0,in.optDouble("item_price_gp",0));int workers=Math.max(1,in.optInt("qualified_workers",1));if(price<=0)return blocked(o,"item_price_required");if(!in.optBoolean("tool_proficient",false)||!in.optBoolean("equipment_available",false))return blocked(o,"appropriate_tool_proficiency_and_equipment_required");return o.put("raw_material_cost_gp",price/2d).put("base_workweeks",price/50d).put("qualified_workers",workers).put("workweeks_required",price/50d/workers).put("multiple_items_under_50_gp_allowed",true).put("result","item_ready_when_time_and_materials_are_paid");}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject craftMagicItem(JSONObject in){JSONObject o=base(129);try{String r=norm(in.optString("rarity"));double[] tc=magicCraft(r);if(tc==null)return blocked(o,"invalid_rarity");if(!in.optBoolean("formula_owned",false))return blocked(o,"formula_required");if(!in.optBoolean("exotic_material_secured",false))return blocked(o,"exotic_material_required");if(!in.optBoolean("tool_or_arcana_proficient",false))return blocked(o,"tool_or_arcana_proficiency_required");int workers=Math.max(1,in.optInt("qualified_workers",1));boolean consumable=in.optBoolean("consumable",false);double weeks=tc[0]*(consumable?0.5:1)/workers,cost=tc[1]*(consumable?0.5:1);return o.put("base_workweeks",tc[0]).put("workweeks_required",weeks).put("gold_cost",cost).put("qualified_workers",workers).put("ingredient_cr_range",ingredientCr(r)).put("consumable_halving_applied",consumable).put("complication_chance_percent_per_5_workweeks",10);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject craftHealingPotion(JSONObject in){JSONObject o=base(130);try{if(!in.optBoolean("herbalism_kit_proficient",false))return blocked(o,"herbalism_kit_proficiency_required");String t=norm(in.optString("potion_type"));if(t.equals("healing")||t.equals("cura"))return o.put("time_days",1).put("gold_cost",25).put("herbalism_kit_proficiency_required",true);if(t.contains("greater")||t.contains("maior"))return o.put("workweeks",1).put("gold_cost",100).put("herbalism_kit_proficiency_required",true);if(t.contains("superior"))return o.put("workweeks",3).put("gold_cost",1000).put("herbalism_kit_proficiency_required",true);if(t.contains("supreme")||t.contains("suprema"))return o.put("workweeks",4).put("gold_cost",10000).put("herbalism_kit_proficiency_required",true);return blocked(o,"invalid_healing_potion_type");}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject crime(JSONObject in){JSONObject o=base(130);try{int dc=in.optInt("target_dc",0),success=clamp(in.optInt("success_count",0),0,3);int potential=dc==10?50:dc==15?100:dc==20?200:dc==25?1000:-1;if(potential<0)return blocked(o,"target_dc_must_be_10_15_20_or_25");if(in.optDouble("prep_gold",0)<25)return blocked(o,"at_least_25_gp_preparation_required");o.put("workweeks",1).put("potential_loot_gp",potential).put("success_count",success);if(success==0)o.put("outcome","caught").put("loot_gp",0).put("fine_gp",potential).put("jail_weeks",potential/25);else if(success==1)o.put("outcome","failed_but_escaped").put("loot_gp",0);else if(success==2)o.put("outcome","partial_success").put("loot_gp",potential/2d);else o.put("outcome","full_success").put("loot_gp",potential);o.put("complication_required",success==1||(success==2&&in.optBoolean("rival_or_law_involved",false)));return o;}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject gambling(JSONObject in){JSONObject o=base(130);try{double stake=in.optDouble("stake_gp",0);if(stake<10||stake>1000)return blocked(o,"stake_must_be_between_10_and_1000_gp_unless_dm_expands_limit");int s=clamp(in.optInt("success_count",0),0,3);double returned=s==0?0:s==1?stake*0.5:s==2?stake*1.5:stake*2;double debt=s==0?stake:0;return o.put("workweeks",1).put("dc_formula_each_check","5 + 2d10").put("three_checks",new JSONArray().put("Wisdom (Insight)").put("Charisma (Deception)").put("Charisma (Intimidation)")).put("success_count",s).put("stake_gp",stake).put("returned_bankroll_gp",returned).put("net_change_gp",returned-stake-debt).put("debt_gp",debt).put("complication_chance_percent",10);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject pitFighting(JSONObject in){JSONObject o=base(131);try{int s=clamp(in.optInt("success_count",0),0,3),gp=s==0?0:s==1?50:s==2?100:200;return o.put("workweeks",1).put("dc_formula_each_check","5 + 2d10").put("checks",new JSONArray().put("Strength (Athletics)").put("Dexterity (Acrobatics)").put("Constitution + largest Hit Die roll (die not spent); one check may be replaced by a weapon attack roll")).put("success_count",s).put("winnings_gp",gp).put("complication_chance_percent",10);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject relax(JSONObject in){JSONObject o=base(131);try{if(in.optInt("workweeks",0)<1)return blocked(o,"one_week_required");if(!in.optBoolean("modest_lifestyle_maintained",false))return blocked(o,"modest_lifestyle_required");return o.put("eligible",true).put("advantage_long_term_disease_poison_recovery_saves",true).put("end_one_nonmagical_effect_blocking_hp_recovery_or_reduced_ability_restore",true).put("continuous_magic_effect_excluded",true);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject religiousService(JSONObject in){JSONObject o=base(131);try{if(!in.optBoolean("aligned_temple_access",false))return blocked(o,"aligned_temple_access_required");int t=in.optInt("check_total",0),gain=t<=10?0:t<=20?1:2,cap=Math.max(1,1+in.optInt("charisma_modifier",0)),cur=Math.max(0,in.optInt("current_favors",0));return o.put("workweeks",1).put("gold_cost",0).put("favors_gained",gain).put("favor_cap",cap).put("favors_after",Math.min(cap,cur+gain)).put("favor_can_reduce_cleric_spellcasting_cost_by_half",true).put("complication_chance_percent",10);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject research(JSONObject in){JSONObject o=base(132);try{if(!in.optBoolean("library_or_sage_access",false))return blocked(o,"library_or_sage_access_required");double spent=in.optDouble("gold_spent",0);if(spent<50)return blocked(o,"at_least_50_gp_required");if(in.optInt("workweeks",0)<1)return blocked(o,"one_workweek_required");int bonus=Math.min(6,(int)Math.floor(Math.max(0,spent-50)/50d));int total=in.optInt("intelligence_total",0)+bonus;int pieces=total<=5?0:total<=10?1:total<=20?2:3;return o.put("gold_spent",spent).put("research_bonus",bonus).put("official_errata","p.132 changes both 100 gp references to 50 gp").put("well_stocked_library_or_sages_grants_advantage",in.optBoolean("well_stocked_access",false)).put("effective_total",total).put("useful_knowledge_pieces",pieces).put("complication_chance_percent",10);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject scribeScroll(JSONObject in){JSONObject o=base(133);try{int level=in.optInt("spell_level",-1);double[] tc=scroll(level);if(tc==null)return blocked(o,"spell_level_must_be_0_to_9");if(!in.optBoolean("arcana_proficient",false)||!in.optBoolean("spell_prepared_or_known",false)||!in.optBoolean("material_components_available",false))return blocked(o,"arcana_spell_and_material_requirements_not_met");if(level<=2)o.put("time_days",(int)tc[0]);else o.put("workweeks",tc[0]);return o.put("gold_cost",tc[1]).put("cantrip_scroll_uses_level_1_caster",level==0).put("complication_chance_percent_per_workweek",10);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject sellMagicItem(JSONObject in){JSONObject o=base(133);try{String r=norm(in.optString("rarity"));double base=saleBase(r);if(base<0)return blocked(o,"invalid_rarity");if(in.optDouble("advertising_gold",0)<25)return blocked(o,"25_gp_advertising_required");if(in.optBoolean("consumable",false))base/=2d;int t=in.optInt("persuasion_total",0);double pct=t<=10?0.5:t<=20?1:1.5;return o.put("workweeks",1).put("base_price_gp",base).put("offer_multiplier",pct).put("offer_gp",base*pct).put("seller_may_refuse_offer",true).put("complication_chance_percent",10);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject training(JSONObject in){JSONObject o=base(134);try{if(!in.optBoolean("instructor_available",false))return blocked(o,"instructor_required");String subject=norm(in.optString("subject_type"));if(!(subject.equals("language")||subject.equals("lingua")||subject.equals("tool")||subject.equals("ferramenta")))return blocked(o,"training_is_language_or_tool_proficiency");int intMod=in.optInt("intelligence_modifier",0),required=Math.max(1,10-Math.max(0,intMod)),spent=Math.max(0,in.optInt("workweeks_spent",0));double cost=required*25d;return o.put("required_workweeks",required).put("gold_cost_total",cost).put("gold_cost_per_workweek",25).put("workweeks_spent",spent).put("complete",spent>=required&&in.optDouble("gold_available",0)>=cost).put("negative_intelligence_does_not_increase_time",true).put("complication_chance_percent_per_10_workweeks",10);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    public static JSONObject work(JSONObject in){JSONObject o=base(134);try{int t=in.optInt("check_total",0);String lifestyle=t<=9?"poor":t<=14?"modest":"comfortable";int bonus=t>=21?25:0;return o.put("workweeks",1).put("allowed_checks",new JSONArray().put("Strength (Athletics)").put("Dexterity (Acrobatics)").put("Intelligence + tool proficiency").put("Charisma (Performance)").put("Charisma + musical instrument proficiency")).put("lifestyle",lifestyle).put("bonus_gold_gp",bonus).put("complication_chance_percent",10);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    private static JSONObject base(int page){JSONObject o=new JSONObject();try{o.put("book",BOOK).put("source_page",page).put("compiled",true).put("auto_rolls",false);}catch(Exception ignored){}return o;}
    private static JSONObject blocked(String reason){return blocked(base(0),reason);}private static JSONObject blocked(JSONObject o,String reason){try{o.put("executed",false).put("blocked",true).put("reason",reason);}catch(Exception ignored){}return o;}
    private static int clamp(int v,int a,int b){return Math.max(a,Math.min(b,v));}
    private static String norm(String s){String x=s==null?"":s.trim().toLowerCase(Locale.ROOT);return x.replace("á","a").replace("ã","a").replace("â","a").replace("é","e").replace("ê","e").replace("í","i").replace("ó","o").replace("ô","o").replace("õ","o").replace("ú","u").replace("ç","c");}
    private static int rarityThreshold(String r){if(r.contains("common")||r.contains("comum"))return r.contains("uncommon")||r.contains("incomum")?15:10;if(r.contains("rare")||r.contains("raro"))return r.contains("very")||r.contains("muito")?25:20;if(r.contains("legend")||r.contains("lend"))return 30;return Integer.MAX_VALUE;}
    private static String priceFormula(String r){String x=norm(r);if(x.isEmpty())return "by rarity: common (1d6+1)x10; uncommon 1d6x100; rare 2d10x1000; very rare (1d4+1)x10000; legendary 2d6x25000; halve consumables";if(x.contains("uncommon")||x.contains("incomum"))return "1d6 x 100 gp";if(x.contains("very")||x.contains("muito"))return "(1d4 + 1) x 10,000 gp";if(x.contains("legend")||x.contains("lend"))return "2d6 x 25,000 gp";if(x.contains("rare")||x.contains("raro"))return "2d10 x 1,000 gp";if(x.contains("common")||x.contains("comum"))return "(1d6 + 1) x 10 gp";return "unknown rarity";}
    private static double priceFromDice(String r,double roll,boolean consumable){String x=norm(r);double p;if(x.contains("uncommon")||x.contains("incomum"))p=roll*100;else if(x.contains("very")||x.contains("muito"))p=(roll+1)*10000;else if(x.contains("legend")||x.contains("lend"))p=roll*25000;else if(x.contains("rare")||x.contains("raro"))p=roll*1000;else p=(roll+1)*10;return consumable?p/2:p;}
    private static double[] magicCraft(String r){String x=norm(r);if(x.contains("uncommon")||x.contains("incomum"))return new double[]{2,200};if(x.contains("very")||x.contains("muito"))return new double[]{25,20000};if(x.contains("legend")||x.contains("lend"))return new double[]{50,100000};if(x.contains("rare")||x.contains("raro"))return new double[]{10,2000};if(x.contains("common")||x.contains("comum"))return new double[]{1,50};return null;}
    private static String ingredientCr(String r){String x=norm(r);if(x.contains("uncommon")||x.contains("incomum"))return "4-8";if(x.contains("very")||x.contains("muito"))return "13-18";if(x.contains("legend")||x.contains("lend"))return "19+";if(x.contains("rare")||x.contains("raro"))return "9-12";return "1-3";}
    private static double saleBase(String r){String x=norm(r);if(x.contains("uncommon")||x.contains("incomum"))return 400;if(x.contains("very")||x.contains("muito"))return 40000;if(x.contains("legend")||x.contains("lend"))return 200000;if(x.contains("rare")||x.contains("raro"))return 4000;if(x.contains("common")||x.contains("comum"))return 100;return -1;}
    private static double[] scroll(int level){switch(level){case 0:return new double[]{1,15};case 1:return new double[]{1,25};case 2:return new double[]{3,250};case 3:return new double[]{1,500};case 4:return new double[]{2,2500};case 5:return new double[]{4,5000};case 6:return new double[]{8,15000};case 7:return new double[]{16,25000};case 8:return new double[]{32,50000};case 9:return new double[]{48,250000};default:return null;}}
}
